canonical_printed_types.SM.IntervalComposition.exists_halfOpen_p:
SM.IntervalComposition.exists_halfOpen_part {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (x : Fin n) (hl : I.left ≤ x) (hr : x < I.right) :
  ∃ k, (π.part k).left ≤ x ∧ x < (π.part k).right

canonical_printed_types.SM.IntervalComposition.part_interior_uni:
SM.IntervalComposition.part_interior_unique {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (x : Fin n) {k l : Fin π.parts} (hk : (π.part k).left < x ∧ x < (π.part k).right)
  (hl : (π.part l).left < x ∧ x < (π.part l).right) : k = l

canonical_printed_types.SM.IntervalComposition.halfOpen_part_uni:
SM.IntervalComposition.halfOpen_part_unique {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (x : Fin n) {k l : Fin π.parts} (hk : (π.part k).left ≤ x ∧ x < (π.part k).right)
  (hl : (π.part l).left ≤ x ∧ x < (π.part l).right) : k = l

canonical_printed_types.SM.IntervalComposition.outer_cuts_subset:
SM.IntervalComposition.outer_cuts_subset_flatten {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n}
  (π : SM.IntervalComposition I) (S : (k : Fin π.parts) → SM.BoundaryCutSet (π.part k)) :
  π.cutSet.cuts ⊆ (π.flattenCutSets S).cuts

canonical_printed_types.SM.IntervalComposition.nearFarWeight_mar:
SM.IntervalComposition.nearFarWeight_marked_expansion.{u} {n : ℕ} [NeZero n] {I : SM.BoundaryInterval n} {R : Type u}
  [CommRing R] [Invertible 2] (π : SM.IntervalComposition I) (D H : SM.TripleArray n R) :
  π.nearFarWeight D H = ∑ marked, (∏ k ∈ marked, -H (π.farTriple k) * ⅟2) * ∏ k ∈ markedᶜ, D (π.nearTriple k) * ⅟2
